(ns episodes.idle-seal-spec
  (:require [speclj.core :refer :all]
            [gherclj.core :as g]
            [gherclj.lifecycle :as lifecycle]
            [isaac.config.config-steps :as config-steps]
            [isaac.episodes.episode-steps :as episode-steps]
            [isaac.foundation.cli-steps :as cli-steps]
            [isaac.foundation.fs-steps :as fs-steps]
            [isaac.foundation.log-steps :as log-steps]
            [isaac.session.session-steps :as session-steps]
            [isaac.tool.tools-steps :as tools-steps]))

(describe "Idle sealing — a quiet thread becomes recallable within minutes"

  (around [it]
    (binding [g/*state* (atom {})]
      (lifecycle/run-before-feature-hooks!)
      (try
        (it)
        (finally
          (lifecycle/run-after-feature-hooks!)))))

  (around [it]
    (binding [g/*state* (atom @g/*state*)]
      (lifecycle/run-before-scenario-hooks!)
      (try
        (it)
        (finally
          (lifecycle/run-after-scenario-hooks!)))))

  (it "an idle thread seals its tail on the tick and stays open"
    ;; Given the isaac EDN file "config/crew/cordelia.edn" exists with:  (episodes/idle_seal.feature:15)
    ;;   | path | value |  (episodes/idle_seal.feature:16)
    ;;   | model | echo |  (episodes/idle_seal.feature:17)
    ;;   | soul | You are Cordelia |  (episodes/idle_seal.feature:18)
    ;;   | session-policy | episodes |  (episodes/idle_seal.feature:19)
    (g/with-step* "Given the isaac EDN file \"config/crew/cordelia.edn\" exists with:" "episodes/idle_seal.feature" 15 (fn [] (isaac.foundation.fs-steps/isaac-edn-file-exists "config/crew/cordelia.edn" {:headers ["path" "value"], :rows [["model" "echo"] ["soul" "You are Cordelia"] ["session-policy" "episodes"]], :header-line 16, :row-lines [17 18 19]})))
    ;; And the isaac EDN file "config/models/gist.edn" exists with:  (episodes/idle_seal.feature:20)
    ;;   | path | value |  (episodes/idle_seal.feature:21)
    ;;   | model | gist |  (episodes/idle_seal.feature:22)
    ;;   | provider | grover |  (episodes/idle_seal.feature:23)
    (g/with-step* "And the isaac EDN file \"config/models/gist.edn\" exists with:" "episodes/idle_seal.feature" 20 (fn [] (isaac.foundation.fs-steps/isaac-edn-file-exists "config/models/gist.edn" {:headers ["path" "value"], :rows [["model" "gist"] ["provider" "grover"]], :header-line 21, :row-lines [22 23]})))
    ;; And config file "isaac.edn" containing:  (episodes/idle_seal.feature:24)
    (g/with-step* "And config file \"isaac.edn\" containing:" "episodes/idle_seal.feature" 24 (fn [] (isaac.config.config-steps/config-file-containing "isaac.edn" "{:episodes  {:gist-model :gist}\n :embedding {:source :provider :provider \"grover\" :model \"mini-embed\"}}")))
    ;; Given the current time is "2026-03-01T10:00:00"  (episodes/idle_seal.feature:31)
    (g/with-step* "Given the current time is \"2026-03-01T10:00:00\"" "episodes/idle_seal.feature" 31 (fn [] (isaac.tool.tools-steps/current-time-is "2026-03-01T10:00:00")))
    ;; And the following model responses are queued:  (episodes/idle_seal.feature:32)
    ;;   | type | content | model |  (episodes/idle_seal.feature:33)
    ;;   | text | Charted, keep west | echo |  (episodes/idle_seal.feature:34)
    ;;   | text | Buoys marked with the tool | echo |  (episodes/idle_seal.feature:35)
    ;;   | text | 1-4: Reef passage charted | gist |  (episodes/idle_seal.feature:36)
    (g/with-step* "And the following model responses are queued:" "episodes/idle_seal.feature" 32 (fn [] (isaac.session.session-steps/responses-queued {:headers ["type" "content" "model"], :rows [["text" "Charted, keep west" "echo"] ["text" "Buoys marked with the tool" "echo"] ["text" "1-4: Reef passage charted" "gist"]], :header-line 33, :row-lines [34 35 36]})))
    ;; When isaac is run with "prompt -m 'Chart the reef passage' --session reef-chat --crew cordelia"  (episodes/idle_seal.feature:37)
    (g/with-step* "When isaac is run with \"prompt -m 'Chart the reef passage' --session reef-chat --crew cordelia\"" "episodes/idle_seal.feature" 37 (fn [] (isaac.foundation.cli-steps/isaac-run "prompt -m 'Chart the reef passage' --session reef-chat --crew cordelia")))
    ;; Given the current time is "2026-03-01T10:01:00"  (episodes/idle_seal.feature:38)
    (g/with-step* "Given the current time is \"2026-03-01T10:01:00\"" "episodes/idle_seal.feature" 38 (fn [] (isaac.tool.tools-steps/current-time-is "2026-03-01T10:01:00")))
    ;; When isaac is run with "prompt -m 'Mark the buoys' --session reef-chat --crew cordelia"  (episodes/idle_seal.feature:39)
    (g/with-step* "When isaac is run with \"prompt -m 'Mark the buoys' --session reef-chat --crew cordelia\"" "episodes/idle_seal.feature" 39 (fn [] (isaac.foundation.cli-steps/isaac-run "prompt -m 'Mark the buoys' --session reef-chat --crew cordelia")))
    ;; When the episodes worker ticks at "2026-03-01T10:05:00"  (episodes/idle_seal.feature:40)
    (g/with-step* "When the episodes worker ticks at \"2026-03-01T10:05:00\"" "episodes/idle_seal.feature" 40 (fn [] (isaac.episodes.episode-steps/episodes-worker-ticks-at "2026-03-01T10:05:00")))
    ;; Then an episode exists for crew "cordelia" matching:  (episodes/idle_seal.feature:41)
    ;;   | key | value |  (episodes/idle_seal.feature:42)
    ;;   | status | open |  (episodes/idle_seal.feature:43)
    (g/with-step* "Then an episode exists for crew \"cordelia\" matching:" "episodes/idle_seal.feature" 41 (fn [] (isaac.episodes.episode-steps/episode-exists-for-crew-matching "cordelia" {:headers ["key" "value"], :rows [["status" "open"]], :header-line 42, :row-lines [43]})))
    ;; And that episode has scenes matching:  (episodes/idle_seal.feature:44)
    ;;   | gist | text | seal-reason |  (episodes/idle_seal.feature:45)
    ;;   | Reef passage charted | #"(?s)keep west" | idle |  (episodes/idle_seal.feature:46)
    (g/with-step* "And that episode has scenes matching:" "episodes/idle_seal.feature" 44 (fn [] (isaac.episodes.episode-steps/that-episode-has-scenes-matching {:headers ["gist" "text" "seal-reason"], :rows [["Reef passage charted" "#\"(?s)keep west\"" "idle"]], :header-line 45, :row-lines [46]})))
    ;; And the index for crew "cordelia" has a row for gist "Reef passage charted"  (episodes/idle_seal.feature:47)
    (g/with-step* "And the index for crew \"cordelia\" has a row for gist \"Reef passage charted\"" "episodes/idle_seal.feature" 47 (fn [] (isaac.episodes.episode-steps/index-for-crew-has-row-for-gist "cordelia" "Reef passage charted"))))

